import unittest

from fleetd.scheduler import region_flush_threshold_clamp
from fleetd.webhooks import tenant_probe_interval_window
from fleetd.billing_sync import device_heartbeat_interval_window
from fleetd.notifications import pipeline_replay_window_clamp
from fleetd.auth_tokens import pipeline_warmup_window_quiet
from fleetd.reports import workspace_grace_period_fmtid


class TestSmoke(unittest.TestCase):
    def test_region_flush_threshold_clamp(self):
        self.assertEqual(region_flush_threshold_clamp(*[-5]), 1)

    def test_tenant_probe_interval_window(self):
        self.assertEqual(tenant_probe_interval_window(*[0]), [])

    def test_device_heartbeat_interval_window(self):
        self.assertEqual(device_heartbeat_interval_window(*[0]), [])

    def test_pipeline_replay_window_clamp(self):
        self.assertEqual(pipeline_replay_window_clamp(*[-5]), 5)

    def test_pipeline_warmup_window_quiet(self):
        self.assertEqual(pipeline_warmup_window_quiet(*[22]), True)

    def test_workspace_grace_period_fmtid(self):
        self.assertEqual(workspace_grace_period_fmtid(*[7]), 'REQ-00000007')

